package com.ykis.ykismobkmp.ui.screens.meterimport androidx.compose.animation.AnimatedVisibilityimport androidx.compose.foundation.backgroundimport androidx.compose.foundation.layout.*import androidx.compose.material3.MaterialThemeimport androidx.compose.runtime.*import androidx.compose.runtime.saveable.rememberSaveableimport androidx.compose.ui.Modifierimport com.ykis.ykismobkmp.domain.entity.HeatMeterEntityimport com.ykis.ykismobkmp.domain.entity.WaterMeterEntityimport com.ykis.ykismobkmp.ui.BaseUIStateimport com.ykis.ykismobkmp.ui.ContentTypeimport com.ykis.ykismobkmp.ui.NavigationTypeimport com.ykis.ykismobkmp.ui.navigation.ContentDetailimport com.ykis.ykismobkmp.ui.screens.meter.components.*private const val className = "MainMeterScreen"@Composablefun MainMeterScreen(  modifier: Modifier = Modifier,  viewModel: MeterViewModel,  baseUIState: BaseUIState,  navigationType: NavigationType,  onDrawerClick: () -> Unit,  contentType: ContentType) {  // 1. ЗАГРУЗКА ДАННЫХ ПРИ СМЕНЕ КВАРТИРЫ  LaunchedEffect(baseUIState.addressId) {    val uid = baseUIState.uid ?: ""    val addressId = baseUIState.addressId    if (uid.isNotEmpty() && addressId > 0) {      Log.d("YkisLog", "[$className.LaunchedEffect]: Loading meters for ID: $addressId")      viewModel.getWaterMeterList(uid, addressId)      viewModel.getHeatMeterList(uid, addressId)    }  }  var selectedTab by rememberSaveable { mutableIntStateOf(0) }  // Используем collectAsState для кроссплатформенности  val waterMeterState by viewModel.waterMeterState.collectAsState()  val heatMeterState by viewModel.heatMeterState.collectAsState()  val showDetail by viewModel.showDetail.collectAsState()  val contentDetail by viewModel.contentDetail.collectAsState()  if (contentType == ContentType.DUAL_PANE) {    // РЕЖИМ ПЛАНШЕТА / MAC (Две панели)    Row(modifier = modifier.fillMaxSize()) {      Box(modifier = Modifier.weight(0.4f)) {        MeterListScreen(          baseUIState = baseUIState,          navigationType = navigationType,          onDrawerClick = onDrawerClick,          viewModel = viewModel,          onWaterMeterClick = { viewModel.setWaterMeterDetail(it) },          onHeatMeterClick = { viewModel.setHeatMeterDetail(it) },          waterMeterState = waterMeterState,          heatMeterState = heatMeterState,          selectedTab = selectedTab,          onTabClick = { selectedTab = it }        )      }      VerticalDivider() // Наш компонент разделителя      Box(modifier = Modifier.weight(0.6f)) {        if (showDetail) {          MeterDetailScreen(            modifier = Modifier.background(MaterialTheme.colorScheme.surface),            contentDetail = contentDetail,            waterMeterState = waterMeterState,            heatMeterState = heatMeterState,            viewModel = viewModel,            baseUIState = baseUIState          )        } else {          EmptyDetailPlaceholder("Виберіть лічильник для перегляду деталей")        }      }    }  } else {    // МОБИЛЬНЫЙ РЕЖИМ (Одна панель)    SinglePanelMeter(      contentDetail = contentDetail,      baseUIState = baseUIState,      navigationType = navigationType,      onDrawerClick = onDrawerClick,      showDetail = showDetail,      viewModel = viewModel,      waterMeterState = waterMeterState,      heatMeterState = heatMeterState,      selectedTab = selectedTab,      onTabClick = { selectedTab = it },      onWaterMeterClick = { viewModel.setWaterMeterDetail(it) },      onHeatMeterClick = { viewModel.setHeatMeterDetail(it) }    )  }}@Composablefun SinglePanelMeter(  modifier: Modifier = Modifier,  contentDetail: ContentDetail,  baseUIState: BaseUIState,  navigationType: NavigationType,  onDrawerClick: () -> Unit,  showDetail: Boolean,  viewModel: MeterViewModel,  waterMeterState: WaterMeterState,  heatMeterState: HeatMeterState,  selectedTab: Int,  onTabClick: (Int) -> Unit,  onWaterMeterClick: (WaterMeterEntity) -> Unit,  onHeatMeterClick: (HeatMeterEntity) -> Unit,) {  Box(modifier = modifier.fillMaxSize()) {    if (!showDetail) {      MeterListScreen(        baseUIState = baseUIState,        navigationType = navigationType,        onDrawerClick = onDrawerClick,        viewModel = viewModel,        onHeatMeterClick = onHeatMeterClick,        onWaterMeterClick = onWaterMeterClick,        waterMeterState = waterMeterState,        heatMeterState = heatMeterState,        selectedTab = selectedTab,        onTabClick = onTabClick      )    }    AnimatedVisibility(visible = showDetail) {      // В KMP используем Voyager/Expect-Actual для обработки кнопки Назад      MeterDetailBackHandler(contentDetail, viewModel)      MeterDetailScreen(        modifier = Modifier.background(MaterialTheme.colorScheme.background),        contentDetail = contentDetail,        waterMeterState = waterMeterState,        heatMeterState = heatMeterState,        viewModel = viewModel,        baseUIState = baseUIState      )    }  }}/** * Хелпер для обработки возврата назад в деталях счетчика */@Composableprivate fun MeterDetailBackHandler(contentDetail: ContentDetail, viewModel: MeterViewModel) {  // В Voyager это можно сделать через LocalNavigator или платформенный BackHandler  com.ykis.ykismobkmp.ui.components.PlatformBackHandler {    Log.d("YkisLog", "[$className.Back]: Closing detail view")    when (contentDetail) {      ContentDetail.WATER_READINGS -> viewModel.setContentDetail(ContentDetail.WATER_METER)      ContentDetail.HEAT_READINGS -> viewModel.setContentDetail(ContentDetail.HEAT_METER)      else -> viewModel.closeContentDetail()    }  }}